CREATE OR REPLACE FUNCTION public.guard_profile_stripe_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.stripe_customer_id IS DISTINCT FROM OLD.stripe_customer_id AND coalesce(current_setting('request.jwt.claim.role',true),'') <> 'service_role' THEN RAISE EXCEPTION 'Stripe identity must be managed by the payment service'; END IF; RETURN NEW; END $$;
CREATE TRIGGER portal_stripe_identity_guard BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_stripe_identity();
CREATE OR REPLACE FUNCTION public.log_portal_charge_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.booking_audit_log(booking_id,booking_user_id,changed_by,action,field,new_value) VALUES(NEW.booking_id,NEW.user_id,NEW.requested_by,'updated','card_charge',NEW.status); ELSIF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.booking_audit_log(booking_id,booking_user_id,changed_by,action,field,old_value,new_value) VALUES(NEW.booking_id,NEW.user_id,NEW.requested_by,'updated','card_charge',OLD.status,NEW.status); END IF; RETURN NEW; END $$;
CREATE TRIGGER portal_charge_audit AFTER INSERT OR UPDATE ON public.portal_charge_requests FOR EACH ROW EXECUTE FUNCTION public.log_portal_charge_changes();
CREATE OR REPLACE FUNCTION public.guard_portal_charge_reservation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings; a public.card_authorizations; paid_cents integer; deposit_cents integer; expected_cents integer; BEGIN SELECT * INTO b FROM public.bookings WHERE id=NEW.booking_id FOR UPDATE; SELECT * INTO a FROM public.card_authorizations WHERE id=NEW.authorization_id FOR UPDATE; IF b.id IS NULL OR a.id IS NULL OR b.user_id IS DISTINCT FROM NEW.user_id OR a.user_id IS DISTINCT FROM NEW.user_id OR a.booking_id IS DISTINCT FROM b.id OR a.revoked_at IS NOT NULL OR a.amount_cents IS DISTINCT FROM NEW.amount_cents OR b.payment_status IN ('paid','refunded') OR b.status IN ('cancelled','canceled','no_show') THEN RAISE EXCEPTION 'Appointment or authorization changed'; END IF; SELECT coalesce(sum((metadata->>'service_amount_cents')::integer),0) INTO paid_cents FROM public.payment_records WHERE booking_id=b.id AND status IN ('succeeded','paid') AND payment_type<>'tip'; IF EXISTS(SELECT 1 FROM public.payment_records WHERE booking_id=b.id AND status IN ('succeeded','paid') AND payment_type<>'tip' AND NOT coalesce(metadata,'{}'::jsonb) ? 'service_amount_cents') THEN RAISE EXCEPTION 'Historical payment requires reconciliation'; END IF; deposit_cents:=CASE WHEN b.payment_status IN ('partial','deposit_paid') THEN round(coalesce(b.deposit_amount,0)*100)::integer ELSE 0 END; SELECT greatest(deposit_cents,coalesce(max(round(q.deposit_amount*100)::integer),0)) INTO deposit_cents FROM public.quotes q WHERE q.booking_id=b.id AND q.stripe_payment_intent_id IS NOT NULL AND q.status IN ('deposit_paid','converted','accepted'); expected_cents:=greatest(0,round(b.total_price*100)::integer-greatest(paid_cents,deposit_cents)); IF expected_cents IS DISTINCT FROM NEW.service_amount_cents OR NEW.amount_cents IS DISTINCT FROM expected_cents+round(expected_cents*0.035)::integer THEN RAISE EXCEPTION 'Balance changed; new customer approval required'; END IF; RETURN NEW; END $$;